Apply the proposed fix as written (it works for both shader styles):

LOOKS = {"glass": (0.05, 0.0), "rubber": (0.85, 0.0), "accent": (0.80, 0.0), "dark": (0.55, 0.45), "steel": (0.35, 0.85),
         "white": (0.40, 0.0), "body": (0.38, 0.0), "hub": (0.38, 0.0), "orange": (0.38, 0.0), "red": (0.38, 0.0)}

def _look(prim, rgb):
    name = prim.GetParent().GetName().lower()
    for key, look in LOOKS.items():
        if name.endswith(key):
            return look
    r, g, b = rgb
    lum, sat = 0.2126 * r + 0.7152 * g + 0.0722 * b, max(rgb) - min(rgb)
    return (0.05, 0.0) if (b > r and b > 0.3 and lum < 0.5) else (0.85, 0.0) if lum < 0.15 else \
        (0.35, 0.85) if sat < 0.08 and lum < 0.7 else (0.38, 0.0)

def tweak_machine_materials(stage, root: str) -> int:
    changed = 0
    for prim in Usd.PrimRange(stage.GetPrimAtPath(root)):
        if not prim.IsA(UsdShade.Shader):
            continue
        sh = UsdShade.Shader(prim)
        color_in = sh.GetInput("diffuseColor") or sh.GetInput("diffuse_color_constant")
        if not color_in or color_in.Get() is None:
            continue
        rough, metal = _look(prim, tuple(color_in.Get()))
        names = (("roughness", "metallic") if sh.GetIdAttr().Get() == "UsdPreviewSurface"
                 else ("reflection_roughness_constant", "metallic_constant"))
        for name, val in zip(names, (rough, metal)):
            (sh.GetInput(name) or sh.CreateInput(name, Sdf.ValueTypeNames.Float)).Set(float(val))
        changed += 1
    return changed

Minor caveat: the description's claim that the shader-type no-op happens is unverified (Isaac Sim not available), so word it as 'may be a no-op'. The name-based lookup assumes the shader's parent prim carries the URDF material name; the colour fallback covers the case where it does not. Dark and accent in particular then depend on the name match, because the colour fallback sends dark (0.2) to the steel branch.

